def describe_locus(idx, key, fids, key_rows, feat_idx, sh_weights, args, insert_anchor_count_by_key):
    locus_id = str(idx)
    asm_fids = [fid for fid in fids if is_assembly_kind(feat_idx[fid]['kind'])]
    medoid_pool = asm_fids if asm_fids else fids
    medoid_fid = choose_medoid_fid(medoid_pool, feat_idx, sh_weights, max_pairwise=args.max_medoid_members)
    lead_fid = medoid_fid if medoid_fid in fids else fids[0]
    display_fid = medoid_fid
    anchor_type = 'primary_ref' if key.startswith('REF::') else 'nonref'
    anchor_ref_fid = key.split('::', 1)[1] if anchor_type == 'primary_ref' else ''
    sample_labels = [str(feat_idx[f]['label']) for f in fids]
    asm_labels = sorted({str(feat_idx[f]['label']) for f in fids if is_assembly_kind(feat_idx[f]['kind'])})
    ref_labels = sorted({str(feat_idx[f]['label']) for f in fids if is_reference_kind(feat_idx[f]['kind'])})
    primary_ref_fids = [f for f in fids if str(feat_idx[f]['kind']) == 'reference_primary']
    comparison_ref_fids = [f for f in fids if str(feat_idx[f]['kind']) == 'reference_comparison']
    rep = feat_idx[medoid_fid]
    nrsite_chrom = ''
    nrsite_start1 = ''
    nrsite_end1 = ''
    nrsite_cluster = 1 if key.startswith('NRSITE::') else 0
    if nrsite_cluster:
        starts = [int(r.get('nonref_site_start1')) for r in key_rows if r.get('nonref_site_start1') not in ('', None)]
        ends = [int(r.get('nonref_site_end1')) for r in key_rows if r.get('nonref_site_end1') not in ('', None)]
        chroms = [str(r.get('nonref_site_chrom') or '') for r in key_rows if str(r.get('nonref_site_chrom') or '')]
        nrsite_chrom = chroms[0] if chroms else ''
        nrsite_start1 = min(starts) if starts else ''
        nrsite_end1 = max(ends) if ends else ''
    return (locus_id, {'anchor_key': key, 'anchor_type': anchor_type, 'anchor_ref_fid': anchor_ref_fid, 'lead_fid': lead_fid, 'medoid_fid': medoid_fid, 'display_fid': display_fid, 'member_n': len(fids), 'hap_n': len(set(sample_labels)), 'asm_hap_n': len(asm_labels), 'ref_hap_n': len(ref_labels), 'primary_ref_member_n': len(primary_ref_fids), 'comparison_ref_member_n': len(comparison_ref_fids), 'has_primary_ref_member': 1 if primary_ref_fids else 0, 'has_comparison_ref_member': 1 if comparison_ref_fids else 0, 'has_any_primary_annot': 1 if any((feat_idx[f].get('primary_chr') for f in fids)) else 0, 'nonref_only_locus': 0 if anchor_type == 'primary_ref' else 1, 'insert_anchor_member_n': int(insert_anchor_count_by_key.get(key, 0)), 'nonref_site_cluster': nrsite_cluster, 'nonref_site_source': key_rows[0].get('nonref_site_source', '') if nrsite_cluster and key_rows else '', 'nonref_site_chrom': nrsite_chrom, 'nonref_site_start1': nrsite_start1, 'nonref_site_end1': nrsite_end1, 'medoid_len': rep['_bp'], 'medoid_left_anchor': '|'.join(rep['_left']), 'medoid_right_anchor': '|'.join(rep['_right']), 'medoid_nodeints_json': json_compact(rep['nodeints']), 'primary_ref_member_fids': ';'.join(primary_ref_fids), 'comparison_ref_member_fids': ';'.join(comparison_ref_fids), 'member_ids': fids})

